const PITCHER_IDX = (VAL && VAL.pitcher_field!==undefined) ? VAL.pitcher_field : undefined;
const PITCH_CATS = ["Fastball","Sinker","Cutter","Slider","Curveball","Changeup","Splitter"];
const PITCHER_HIDE_CATS = ["Arm Strength - Infield","Arm Strength - Outfield","Catchers","Timing Gates","60 Yard Time","Home to 1B","Max EV"];
const NAME2IDX = {}; SCHEMA.ui_groups.forEach(g=>g.fields.forEach(f=>{NAME2IDX[f.name]=f.idx;}));
const EVENT_IDX = SCHEMA.field_row.indexOf('event_date');
// Fold a name for case- AND accent-insensitive comparison / search, so
// "José" and "Jose" are treated as the same player and a search for "jose"
// finds "José". Lowercases, strips diacritics (NFD + combining marks), and trims.
function _fold(s){ try{ return String(s==null?'':s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim(); }catch(e){ return String(s==null?'':s).toLowerCase().trim(); } }
let eventDate='';

// ---- events (each event owns its own list of players; persisted locally) ----
const EVENTS_KEY='measurables_events_v2';
let events=[];      // [{name,date,players:[...]}]
let activeIdx=-1;   // index of the active event, -1 = none
let players=[];     // reference to events[activeIdx].players
let current=0;
let popupMenuMode='legacy'; // 'legacy' (all players listed) or 'dropdown' (pick one)
let _popupSearchClear=null; // when a dropdown-mode popup is open, clears its search box on any update

function hasActiveEvent(){ return activeIdx>=0 && activeIdx<events.length; }
function applyEventDate(){ if(EVENT_IDX<0) return; players.forEach(p=>{ p[EVENT_IDX]=eventDate; }); }
// Event-level Time of Day: the single setting that tags every piece of tech
// captured in the Data Entry tab. New device entries default to it, and
// changing it stamps all existing device entries for the active event.
function getEventTod(){ return (hasActiveEvent() && events[activeIdx].data && events[activeIdx].data.tod) || 'Morning'; }
function applyEventTod(v){
  if(!hasActiveEvent()) return;
  const data=ensureData(events[activeIdx]);
  data.tod=v;
  Object.keys(data.devices||{}).forEach(dk=>{
    (data.devices[dk].players||[]).forEach(dp=>{ dp.tod=v; });
  });
  persistEvents();
  if(mode==='data') renderDataEntry();
}

function loadEvents(){
  try{ events=JSON.parse(localStorage.getItem(EVENTS_KEY)||'[]'); }catch(e){ events=[]; }
  if(!Array.isArray(events)) events=[];
  events.forEach(ev=>{ if(!Array.isArray(ev.players)) ev.players=[]; });
}
function persistEvents(){
  if(hasActiveEvent()){ events[activeIdx].players=players; events[activeIdx].date=eventDate; }
  try{ localStorage.setItem(EVENTS_KEY,JSON.stringify(events)); }catch(e){}
  if(hasActiveEvent() && players[current]) scheduleDBSync(players[current]);
  if(_popupSearchClear){ try{ _popupSearchClear(); }catch(e){} }
}
function renderSavedEvents(sel){
  const dd=document.getElementById('savedEvents'); if(!dd) return;
  dd.innerHTML='';
  const blank=document.createElement('option');blank.value='';
  blank.textContent=events.length?'-- select saved event --':'(no saved events yet)';
  dd.appendChild(blank);
  // Show events ordered by date (oldest first); undated events fall to the end.
  // Option values stay the ORIGINAL array index so activeIdx and every other
  // index reference keep working regardless of display order.
  const order=events.map((ev,i)=>i).sort((a,b)=>{
    const ka=mdyToISO(events[a].date||''), kb=mdyToISO(events[b].date||'');
    if(ka&&kb){ if(ka<kb) return -1; if(ka>kb) return 1; }
    else if(ka&&!kb) return -1;
    else if(!ka&&kb) return 1;
    return a-b; // stable tie-break by original order
  });
  order.forEach(i=>{
    const ev=events[i];
    const o=document.createElement('option');o.value=String(i);
    const n=(ev.players?ev.players.length:0);
    o.textContent=(ev.name||'(unnamed)')+(ev.date?(' \u2013 '+ev.date):'')+' \u2022 '+n+' player'+(n!==1?'s':'')+(ev._dbId?' \u2022 DB':'');
    dd.appendChild(o);
  });
  if(sel!==undefined && sel!==null) dd.value=String(sel);
}
// Pull events saved in the database (Events collection) into the same dropdown so
// every saved event is reachable, AND keep already-known events in sync: when a
// DB event we already have locally changes on another device (e.g. its player
// list grows), refresh our copy so the update actually shows up here.
function applyDbEvents(list){
  if(!Array.isArray(list)) return;
  var changed=false;       // local events changed -> persist + refresh dropdown
  var activeChanged=false; // the ACTIVE event's contents changed -> re-render roster
  var refreshed=0;         // existing events whose contents were updated from the cloud
  // Don't fight the user while a popup editor (Edit Players / Tech) is open.
  var ov=document.getElementById('overlay'), ov2=document.getElementById('overlay2');
  var popupOpen=(ov&&ov.classList.contains('show'))||(ov2&&ov2.classList.contains('show'));
  list.forEach(function(docu){
    var id=docu&&(docu.event_id||docu._id); if(!id) return;
    // Find an existing local event tracking this DB doc id.
    var idx=-1;
    for(var i=0;i<events.length;i++){ if(events[i]._dbId===id){ idx=i; break; } }
    if(idx<0){
      // A local event created here (same computed id) but not yet stamped with
      // its _dbId (e.g. saved to DB from another page). Adopt it instead of
      // duplicating.
      for(var j=0;j<events.length;j++){ if(!events[j]._dbId && eventDocId(events[j])===id){ idx=j; events[j]._dbId=id; changed=true; break; } }
    }
    // Parse the incoming payload.
    var parsed=null; try{ parsed=JSON.parse(docu.data||'null'); }catch(e){}
    // A "real" payload actually carries event content (name/date/players).
    var hasPayload=!!(parsed&&typeof parsed==='object'&&(parsed.players!==undefined||parsed.name!==undefined||parsed.date!==undefined));
    var incoming=(parsed&&typeof parsed==='object')?parsed:{name:docu.name||'',date:docu.date||'',players:[]};
    if(!Array.isArray(incoming.players)) incoming.players=[];
    if(idx<0){
      // Brand-new event from another device -> add it.
      incoming._dbId=id; incoming._fromDb=true;
      events.push(incoming); changed=true;
      return;
    }
    // Existing event -> refresh contents if the DB copy differs. Skip degenerate
    // pings that carry no real payload so we never wipe a good local copy.
    if(!hasPayload) return;
    var ev=events[idx];
    var isActive=(activeIdx===idx);
    // Don't overwrite the active event while the user is editing it.
    if(isActive && (popupOpen || isFormFieldFocused())) return;
    // Existing event -> MERGE the incoming DB copy into the local one instead of
    // overwriting it, so a player that already has information locally keeps that
    // information and simply gains anything new captured on the other device.
    // Local values win on conflicts (blanks are back-filled from incoming);
    // player rosters are deduped by Cubs ID / name, and device/tech entries are
    // unioned. Event name/date follow the incoming (latest) save.
    var incEv={ name:(incoming.name||''), date:(incoming.date||''), players:incoming.players,
                data:(incoming.data!==undefined?incoming.data:ev.data) };
    var merged=computeMergedEvent([ev, incEv], true);
    // Preserve a Time of Day set on the other device if we don't have one locally.
    if((!ev.data||!ev.data.tod) && incoming.data && incoming.data.tod && merged.data){ merged.data.tod=incoming.data.tod; }
    var newName=(incoming.name!==undefined?(incoming.name||''):(ev.name||''));
    var newDate=(incoming.date!==undefined?(incoming.date||''):(ev.date||''));
    var before=JSON.stringify({n:ev.name||'',d:ev.date||'',p:ev.players||[],x:ev.data||null});
    var after=JSON.stringify({n:newName,d:newDate,p:merged.players,x:merged.data});
    if(before===after) return; // nothing new for this event
    ev.name=newName; ev.date=newDate; ev.players=merged.players;
    // Merged Data Entry payload (device links / IDs / Time of Day) so tech captured
    // on another device shows up here without discarding tech captured locally.
    ev.data=merged.data;
    changed=true; refreshed++;
    if(isActive){
      // Re-point the live roster reference and refresh the view.
      players=ev.players;
      if(current>=players.length) current=Math.max(0,players.length-1);
      eventDate=ev.date||'';
      var dtEl=document.getElementById('eventDate'); if(dtEl) dtEl.value=mdyToISO(eventDate);
      var nmEl=document.getElementById('eventName'); if(nmEl) nmEl.value=ev.name||'';
      activeChanged=true;
    }
  });
  if(changed){
    try{ localStorage.setItem(EVENTS_KEY,JSON.stringify(events)); }catch(e){}
    renderSavedEvents(hasActiveEvent()?activeIdx:undefined);
    updateGate();
    if(activeChanged){ renderPlayers(); renderForm(); renderDataEntry(); }
    // Visible confirmation that an inbound change actually arrived from another
    // device (helps distinguish a sync problem from a rendering problem).
    if(refreshed>0){ try{ showToast('Synced update from another device'); }catch(e){} }
  }
}
if(typeof window!=='undefined') window.__applyDbEvents=applyDbEvents;
function updateGate(){
  const on=hasActiveEvent();
  ['addPlayer','addPlayerTop'].forEach(id=>{
    const b=document.getElementById(id); if(!b) return;
    b.disabled=!on; b.style.opacity=on?'':'0.45'; b.style.cursor=on?'':'not-allowed';
  });
  const note=document.getElementById('eventDateNote');
  if(note){
    if(!on){ note.textContent='Create or select an event to start adding players'; }
    else { const ev=events[activeIdx]; note.textContent='Active event: '+(ev.name||'(unnamed)')+(ev.date?(' \u2013 '+ev.date):'')+' \u2022 '+players.length+' player'+(players.length!==1?'s':''); }
  }
}
function setActiveEvent(i){
  if(i<0||i>=events.length) return;
  activeIdx=i;
  const ev=events[i];
  players=ev.players;
  current=0;
  eventDate=ev.date||'';
  const dtEl=document.getElementById('eventDate'); if(dtEl) dtEl.value=mdyToISO(eventDate);
  const nmEl=document.getElementById('eventName'); if(nmEl) nmEl.value=ev.name||'';
  ensureData(ev);
  const todEl=document.getElementById('eventTod'); if(todEl) todEl.value=ev.data.tod||'Morning';
  renderSavedEvents(i);
  updateGate();
  renderPlayers();
  renderForm();
  renderDataEntry();
}
function createEvent(){
  openModal(
    '<h3 style="margin:0 0 4px">Create event</h3>'+
    '<p style="margin:0 0 16px;color:var(--muted);font-size:13px">Set the date and name for the new event.</p>'+
    '<div style="margin-bottom:14px"><label style="display:block;font-size:12px;color:var(--muted);margin:0 0 6px 2px;font-weight:600">Event date</label>'+
    '<input type="date" id="mEvtDate" style="width:100%;box-sizing:border-box;background:#0b1220;border:1px solid var(--line);border-radius:8px;color:var(--txt);padding:9px 11px;font-size:14px;color-scheme:dark" /></div>'+
    '<div style="margin-bottom:4px"><label style="display:block;font-size:12px;color:var(--muted);margin:0 0 6px 2px;font-weight:600">Event name</label>'+
    '<input type="text" id="mEvtName" placeholder="e.g. Fall Combine" style="width:100%;background:#0b1220;border:1px solid var(--line);border-radius:8px;color:var(--txt);padding:9px 11px;font-size:14px" /></div>'+
    '<div style="display:flex;gap:10px;justify-content:flex-end;margin-top:18px"><button class="ghost" id="mEvtCancel">Cancel</button><button class="primary" id="mEvtSave">Create</button></div>'
  );
  // Pre-fill from the top-bar fields if they have values
  var dIn=document.getElementById('mEvtDate');
  var nIn=document.getElementById('mEvtName');
  if(dIn) dIn.value=(document.getElementById('eventDate').value||'');
  if(nIn) nIn.value=(document.getElementById('eventName').value||'');
  var cx=document.getElementById('mEvtCancel'); if(cx) cx.addEventListener('click',closeModal);
  var sv=document.getElementById('mEvtSave');
  if(sv) sv.addEventListener('click',function(){
    var nm=(nIn?nIn.value:'').trim();
    var dt=isoToMDY((dIn?dIn.value:'').trim());
    if(!nm && !dt){ showToast('Enter an event name or date first'); return; }
    events.push({name:nm,date:dt,players:[]});
    setActiveEvent(events.length-1);
    // Sync top-bar fields to the new event values
    var topDate=document.getElementById('eventDate'); if(topDate) topDate.value=mdyToISO(dt);
    var topName=document.getElementById('eventName'); if(topName) topName.value=nm;
    persistEvents();
    showToast('Event created');
    closeModal();
  });
}
function addPlayer(){
  if(!hasActiveEvent()){ showToast('Create or select an event first'); return; }
  const p=blankPlayer(); if(EVENT_IDX>=0)p[EVENT_IDX]=eventDate;
  players.push(p); current=players.length-1;
  persistEvents(); renderSavedEvents(activeIdx); updateGate();
  renderPlayers(); renderForm();
}
function closeModal(){ const ov=document.getElementById('overlay'); if(ov){ ov.classList.remove('show'); const md=document.getElementById('modal'); if(md) md.innerHTML=''; } }
function openModal(html){ const ov=document.getElementById('overlay'), md=document.getElementById('modal'); if(!ov||!md) return; md.innerHTML=html; ov.classList.add('show'); }
function openModalNode(node){ const ov=document.getElementById('overlay'), md=document.getElementById('modal'); if(!ov||!md) return; md.innerHTML=''; md.appendChild(node); ov.classList.add('show'); }
function elItem(tag,props,style){ const e=document.createElement(tag); if(props) Object.keys(props).forEach(k=>{ e[k]=props[k]; }); if(style) e.style.cssText=style; return e; }
function fieldLabel(t){ return elItem('label',{textContent:t},'display:block;font-size:12px;color:var(--muted);font-weight:600;margin:0 0 6px 2px'); }
function txtInput(val){ const i=document.createElement('input');i.type='text';i.value=val||'';i.style.cssText='width:100%;box-sizing:border-box;background:#0b1220;border:1px solid var(--line);border-radius:8px;color:var(--txt);padding:8px 10px;font-size:13px';return i; }
function openModal2Node(node){ const ov=document.getElementById('overlay2'), md=document.getElementById('modal2'); if(!ov||!md) return; md.innerHTML=''; md.appendChild(node); ov.classList.add('show'); }
function closeModal2(){ const ov=document.getElementById('overlay2'); if(ov){ ov.classList.remove('show'); const md=document.getElementById('modal2'); if(md) md.innerHTML=''; } }
function fRange(a,b,step){ const out=[]; const A=Math.round(a*100),B=Math.round(b*100),S=Math.round(step*100); for(var c=A;c<=B;c+=S) out.push(c/100); return out; }
function fmt2(n){ return Number(n).toFixed(2); }
const YARD_OPTS={ '10':fRange(1.40,1.90,0.10), '20':fRange(2.50,3.50,0.10), '30':fRange(3.50,4.40,0.10), '40':fRange(4.30,5.80,0.10), '60':fRange(6.20,9.00,0.10) };
const POP_OPTS=fRange(1.60,2.50,0.10);
function pickButton(val){
  const b=document.createElement('button');b.type='button';
  const has=(val!==undefined&&val!=='');
  b.style.cssText='width:100%;box-sizing:border-box;text-align:left;background:#0b1220;border:1px solid var(--line);border-radius:8px;color:'+(has?'var(--txt)':'var(--muted)')+';padding:8px 10px;font-size:13px;font-weight:600';
  b.textContent=has?val:'Select\u2026';
  return b;
}
function openStepPicker(title, coarse, disp, targetStep, onPick){
  const gridCss='display:grid;grid-template-columns:repeat(auto-fill,minmax(76px,1fr));gap:8px;margin-top:6px';
  const step1=(coarse.length>1)?(coarse[1]-coarse[0]):1;
  const show=(ttl,opts,step,backFn)=>{
    const isFinal = step<=targetStep+1e-9;
    const root=document.createElement('div');
    root.appendChild(elItem('h3',{textContent:ttl},'margin:0 0 4px;font-size:17px'));
    root.appendChild(elItem('p',{className:'sub2',textContent:isFinal?'Pick the exact value.':'Pick a value, then refine.'}));
    const grid=document.createElement('div');grid.style.cssText=gridCss;
    opts.forEach(o=>{
      const b=elItem('button',{className:'segtab',textContent:disp(o,step)});b.style.cssText='padding:12px 6px;font-size:14px';
      b.addEventListener('click',()=>{
        if(isFinal){ closeModal2(); onPick(disp(o,step)); }
        else { const ns=step/10; const no=[]; for(var i=0;i<=9;i++) no.push(Math.round((o+i*ns)*1000)/1000); show(title+' \u2013 '+disp(o,step), no, ns, ()=>show(ttl,opts,step,backFn)); }
      });
      grid.appendChild(b);
    });
    root.appendChild(grid);
    const acts=document.createElement('div');acts.style.cssText='display:flex;gap:10px;margin-top:16px;justify-content:'+(backFn?'space-between':'flex-end');
    if(backFn){ const back=elItem('button',{className:'ghost',textContent:'\u2190 Back'});back.addEventListener('click',backFn);acts.appendChild(back); }
    const cancel=elItem('button',{className:'ghost',textContent:'Cancel'});cancel.addEventListener('click',closeModal2);acts.appendChild(cancel);
    root.appendChild(acts);
    openModal2Node(root);
  };
  show(title, coarse, step1, null);
}
function openValuePicker(title, coarse, onPick){ openStepPicker(title, coarse, (v)=>fmt2(v), 0.01, onPick); }
function openIntPicker(title, min, max, onPick){
  const root=document.createElement('div');
  root.appendChild(elItem('h3',{textContent:title},'margin:0 0 4px;font-size:17px'));
  root.appendChild(elItem('p',{className:'sub2',textContent:'Pick a number.'}));
  const grid=document.createElement('div');grid.style.cssText='display:grid;grid-template-columns:repeat(auto-fill,minmax(54px,1fr));gap:8px;margin-top:6px';
  for(var n=min;n<=max;n++){ (function(v){ const b=elItem('button',{className:'segtab',textContent:String(v)});b.style.cssText='padding:10px 4px;font-size:14px';b.addEventListener('click',()=>{ closeModal2(); onPick(String(v)); });grid.appendChild(b); })(n); }
  root.appendChild(grid);
  const acts=document.createElement('div');acts.style.cssText='display:flex;gap:10px;justify-content:flex-end;margin-top:16px';
  const cancel=elItem('button',{className:'ghost',textContent:'Cancel'});cancel.addEventListener('click',closeModal2);
  acts.appendChild(cancel);root.appendChild(acts);
  openModal2Node(root);
}
// Two-step Max/AVG picker for tech readings: coarse (50..110) -> exact (NN..NN+9), plus Blank.
function openValuesPicker(title, current, onSave){
  const COARSE=[50,60,70,80,90,100,110];
  const sel={value:(current===undefined?null:current)}; // null=nothing picked, ''=blank, 'NN'=value
  const root=document.createElement('div');
  root.appendChild(elItem('h3',{textContent:title},'margin:0 0 4px;font-size:17px'));
  root.appendChild(elItem('p',{className:'sub2',textContent:'Pick a range, then the exact value \u2014 or choose Blank.'}));
  const cgrid=document.createElement('div');cgrid.style.cssText='display:grid;grid-template-columns:repeat(auto-fill,minmax(64px,1fr));gap:8px;margin-top:6px';
  const fineWrap=document.createElement('div');fineWrap.style.cssText='margin-top:12px';
  const fineLbl=elItem('div',{textContent:'Exact value'},'font-size:12px;color:var(--muted);font-weight:700;margin:0 0 6px 2px;display:none');
  const fgrid=document.createElement('div');fgrid.style.cssText='display:grid;grid-template-columns:repeat(auto-fill,minmax(54px,1fr));gap:8px';
  fineWrap.appendChild(fineLbl);fineWrap.appendChild(fgrid);
  let activeCoarse=null, blankBtn=null;
  function paintCoarse(){ Array.from(cgrid.children).forEach(b=>{ b.classList.toggle('active', b===activeCoarse || (b._blank && sel.value==='')); }); }
  function paintFine(){ Array.from(fgrid.children).forEach(b=>{ b.classList.toggle('active', String(b._v)===String(sel.value)); }); }
  function showFine(base){ fgrid.innerHTML=''; fineLbl.style.display=''; for(var i=0;i<10;i++){ (function(v){ const b=elItem('button',{className:'segtab',textContent:String(v)}); b.style.cssText='padding:10px 4px;font-size:14px'; b._v=v; b.addEventListener('click',()=>{ sel.value=String(v); paintFine(); }); fgrid.appendChild(b); })(base+i); } paintFine(); }
  COARSE.forEach(c=>{ const b=elItem('button',{className:'segtab',textContent:String(c)}); b.style.cssText='padding:12px 6px;font-size:14px'; b.addEventListener('click',()=>{ activeCoarse=b; sel.value=null; paintCoarse(); showFine(c); }); cgrid.appendChild(b); });
  blankBtn=elItem('button',{className:'segtab',textContent:'Blank'}); blankBtn.style.cssText='padding:12px 6px;font-size:14px'; blankBtn._blank=true; blankBtn.addEventListener('click',()=>{ activeCoarse=null; sel.value=''; fgrid.innerHTML=''; fineLbl.style.display='none'; paintCoarse(); }); cgrid.appendChild(blankBtn);
  root.appendChild(cgrid); root.appendChild(fineWrap);
  if(current!==undefined){ if(current===''){ sel.value=''; } else { const n=parseInt(current,10); if(!isNaN(n)){ const base=Math.floor(n/10)*10; const cb=Array.from(cgrid.children).find(x=>x.textContent===String(base)); if(cb){ activeCoarse=cb; showFine(base); } sel.value=String(n); } } paintCoarse(); paintFine(); }
  const acts=document.createElement('div');acts.style.cssText='display:flex;gap:10px;justify-content:flex-end;margin-top:18px';
  const cancel=elItem('button',{className:'ghost',textContent:'Cancel'});cancel.addEventListener('click',closeModal2);
  const save=elItem('button',{className:'primary',textContent:'Save'});
  save.addEventListener('click',()=>{ if(sel.value===null){ showToast('Pick a value or choose Blank'); return; } closeModal2(); onSave(sel.value); });
  acts.appendChild(cancel);acts.appendChild(save);root.appendChild(acts);
  openModal2Node(root);
}
// A "Values\u2026" control that captures Max then AVG; collapses to "Max: NN  AVG: NN" once set.
function buildValuesControl(p, key){
  const host=document.createElement('span');
  host.style.cssText='display:inline-flex;gap:6px;align-items:center;flex-wrap:wrap';
  function openFlow(){
    openValuesPicker('Max Value', p._dev[key+'Max'], (maxVal)=>{
      openValuesPicker('AVG Value', p._dev[key+'Avg'], (avgVal)=>{
        p._dev[key+'Max']=maxVal; p._dev[key+'Avg']=avgVal;
        render(); persistEvents(); if(mode==='data') renderDataEntry();
      });
    });
  }
  function render(){
    host.innerHTML='';
    const hasMax=p._dev[key+'Max']!==undefined, hasAvg=p._dev[key+'Avg']!==undefined;
    if(!hasMax && !hasAvg){
      const b=document.createElement('button');b.type='button';b.textContent='Values\u2026';
      b.style.cssText='background:#0b1220;border:1px solid var(--line);border-radius:8px;color:var(--muted);padding:8px 10px;font-size:13px;font-weight:600';
      b.addEventListener('click',openFlow); host.appendChild(b);
    } else {
      const mk=(lbl,v)=>{ const d=document.createElement('button');d.type='button'; const txt=(v===undefined||v==='')?'\u2014':String(v); d.textContent=lbl+': '+txt; d.style.cssText='background:#0b1220;border:1px solid var(--line);border-radius:8px;color:var(--txt);padding:8px 10px;font-size:13px;font-weight:600'; d.addEventListener('click',openFlow); return d; };
      host.appendChild(mk('Max',p._dev[key+'Max'])); host.appendChild(mk('AVG',p._dev[key+'Avg']));
    }
  }
  host._sync=render; render(); return host;
}
