function addPlayerFull(opt){
  if(!hasActiveEvent()){ showToast('Create or select an event first'); return; }
  opt=opt||{};
  const p=blankPlayer(); if(EVENT_IDX>=0)p[EVENT_IDX]=eventDate;
  if(opt.name && NAME_IDX!==undefined) p[NAME_IDX]=opt.name;
  if(opt.id && PIDCUBS_IDX!==undefined) p[PIDCUBS_IDX]=opt.id;
  if(opt.pitcher && PITCHER_IDX!==undefined){ p[PITCHER_IDX]=true; }
  else if(opt.pos && POS){ p[POS.field]=opt.pos; applyPosition(p); }
  p._bats=opt.bats||'';
  p._throws=opt.throws||'';
  p._class=opt.cls||'';
  p._dob=opt.dob||'';
  players.push(p); current=players.length-1;
  persistEvents(); renderSavedEvents(activeIdx); updateGate();
  renderPlayers(); renderForm();
}
function msegHtml(label,group,opts){
  const b=opts.map(o=>'<div class="segtab" data-g="'+group+'" data-v="'+o+'">'+o+'</div>').join('');
  return '<div class="seg-group" style="margin-top:12px"><div class="lbl">'+label+'</div><div class="segtabs">'+b+'</div></div>';
}
