  const selStyle='style="width:100%;box-sizing:border-box;background:#0b1220;border:1px solid var(--line);border-radius:8px;color:var(--txt);padding:10px 12px;font-size:14px"';
  let classOpts='<option value="">Select class\u2026</option>'; for(var _y=2016;_y<=2037;_y++){ classOpts+='<option value="'+_y+'">'+_y+'</option>'; }
