function parseCSV(text){
  const rows=[]; let row=[]; let cur=''; let q=false;
  for(let i=0;i<text.length;i++){
    const ch=text[i];
    if(q){ if(ch==='"'){ if(text[i+1]==='"'){cur+='"';i++;} else q=false; } else cur+=ch; }
    else {
      if(ch==='"') q=true;
      else if(ch===','){ row.push(cur); cur=''; }
      else if(ch==='\r'){ }
      else if(ch==='\n'){ row.push(cur); rows.push(row); row=[]; cur=''; }
      else cur+=ch;
    }
  }
  if(cur!==''||row.length){ row.push(cur); rows.push(row); }
  return rows;
}
function importCSV(text,fileName){
  const rows=parseCSV(text).filter(r=>r.some(c=>String(c).trim()!==''));
  if(!rows.length){ showToast('CSV is empty'); return; }
  const fkey=SCHEMA.field_row.map(x=>String(x).trim());
  let dataStart=0;
  for(let i=0;i<Math.min(rows.length,3);i++){
    const r=rows[i].map(x=>String(x).trim());
    const matches=r.filter((c,j)=>c!=='' && c===fkey[j]).length;
    if(matches>Math.max(3,fkey.length*0.5)) dataStart=i+1;
  }
  const newPlayers=[];
  for(let i=dataStart;i<rows.length;i++){
    const r=rows[i];
    const p=blankPlayer();
    for(let c=0;c<NCOL;c++){
      const raw=(r[c]!==undefined)?String(r[c]):'';
      if(BOOL.has(c)) p[c]=/^\s*true\s*$/i.test(raw);
      else p[c]=raw;
    }
    newPlayers.push(p);
  }
  if(!newPlayers.length){ showToast('No player rows found in CSV'); return; }
  const nm=(fileName||'Imported').replace(/\.csv$/i,'');
  const dt=(EVENT_IDX>=0 && newPlayers[0][EVENT_IDX])?newPlayers[0][EVENT_IDX]:'';
  events.push({name:nm,date:dt,players:newPlayers});
  setActiveEvent(events.length-1);
  persistEvents();
  showToast('Loaded '+newPlayers.length+' player'+(newPlayers.length!==1?'s':'')+' from CSV');
}
