function exportDataMapping(){
  if(!hasActiveEvent()){ showToast('Create or select an event first'); return; }
  if(players.length===0){ showToast('Add at least one player before exporting'); return; }
  var exclPitch=document.getElementById('excludePitchers');
  var excludeP=exclPitch&&exclPitch.checked;
  var exportPlayers=excludeP ? players.filter(function(p){ return !(PITCHER_IDX!==undefined && p[PITCHER_IDX]===true); }) : players;
  if(!exportPlayers.length){ showToast('No players to export after excluding pitchers'); return; }
  var data=ensureData(events[activeIdx]);
  var low=function(v){ return String(v===undefined||v===null?'':v).toLowerCase(); };
  // Device layout: two slots each for Trackman, Blast, Forceplates.
  // Note: Forceplates uses lower-case Bats/Throws header labels (bats/throws)
  // to match the required export format exactly.
  var DEV_EXPORT=[
    {key:'trackman',   label:'Trackman',    bt:'Bats', tt:'Throws'},
    {key:'blast',      label:'Blast',       bt:'Bats', tt:'Throws'},
    {key:'forceplate', label:'Forceplates', bt:'bats', tt:'throws'}
  ];
  var SLOTS=2;
  var TOTAL=5+DEV_EXPORT.length*SLOTS*5;
  // Row 1: "Metadata" marker spanning every column.
  var meta=['Metadata']; while(meta.length<TOTAL) meta.push('');
  // Row 2: headers.
  var hdr=['Name','player_id_cubs','event_date','is_pitcher_test','Position'];
  DEV_EXPORT.forEach(function(d){
    for(var s=0;s<SLOTS;s++){
      hdr.push(d.label+'_ID', d.label, d.label+'_'+d.bt, d.label+'_'+d.tt, d.label+'_tod');
    }
  });
  var lines=[meta.map(csvCell).join(','), hdr.map(csvCell).join(',')];
  exportPlayers.forEach(function(p){
    // Skip players with no tech/data taken: if they aren't linked to ANY of the
    // exported devices, they are left out of the Data CSV entirely.
    var hasAny=DEV_EXPORT.some(function(d){
      var arr=(data.devices[d.key]&&data.devices[d.key].players)||[];
      return arr.some(function(x){ return x.linkPid===p._pid; });
    });
    if(!hasAny) return;
    var pit=(PITCHER_IDX!==undefined && p[PITCHER_IDX]===true);
    var pos=pit?'P':((POS&&p[POS.field])?String(p[POS.field]):'');
    var evd=(EVENT_IDX>=0 && p[EVENT_IDX])?p[EVENT_IDX]:(eventDate||'');
    var row=[ playerName(p), (PIDCUBS_IDX!==undefined?(p[PIDCUBS_IDX]||''):''), evd, pit?'TRUE':'FALSE', pos ];
    DEV_EXPORT.forEach(function(d){
      var arr=(data.devices[d.key]&&data.devices[d.key].players)||[];
      var mine=arr.filter(function(x){ return x.linkPid===p._pid; });
      for(var s=0;s<SLOTS;s++){
        var e=mine[s];
        if(e){ row.push(e.id||'', e.accountName||'', low(e.bats), low(e.throws), low(e.tod)); }
        else { row.push('','','','',''); }
      }
    });
    lines.push(row.map(csvCell).join(','));
  });
  var blob=new Blob([lines.join('\r\n')],{type:'text/csv;charset=utf-8;'});
  var url=URL.createObjectURL(blob);
  var a=document.createElement('a');a.href=url;a.download=exportFileName('data_export');
  document.body.appendChild(a);a.click();document.body.removeChild(a);URL.revokeObjectURL(url);
  showToast('Data CSV exported'+(excludeP?' (pitchers excluded)':''));
}
