function blankDev(){ return {trackman:false,blast:false,forceplate:false,blastNum:'',trackmanTxt:'',forceplateTxt:'',blastR:false,blastL:false,blastTxt:'',blastTxtR:'',blastTxtL:''}; }
// Keep a player's device checkboxes in lock-step with the Data Entry rows that
// are actually linked to them. A profile synced from another device can end up
