  if(!hasActiveEvent()) return;
  const data=ensureData(events[activeIdx]);
  const pid=ensurePid(p);
  ['trackman','forceplate','timinggates','dynamo'].forEach(dk=>{
    const arr=(data.devices[dk]&&data.devices[dk].players)||[];
    p._dev[dk]=arr.some(x=>x.linkPid===pid);
  });
  const blastArr=(data.devices.blast&&data.devices.blast.players)||[];
  const mine=blastArr.filter(x=>x.linkPid===pid);
  p._dev.blast=mine.length>0;
  p._dev.blastR=mine.some(x=>(x.hand||'')==='R');
  p._dev.blastL=mine.some(x=>(x.hand||'')==='L');
