      const search=document.createElement('input');
      search.type='text'; search.placeholder='Search player\u2026';
      search.style.cssText='width:100%;box-sizing:border-box;background:#0b1220;border:1px solid var(--line);border-radius:8px;color:var(--txt);padding:9px 11px;font-size:14px;margin:0 0 8px';
      const sel=document.createElement('select');
      sel.style.cssText='width:100%;box-sizing:border-box;background:#0b1220;border:1px solid var(--line);border-radius:8px;color:var(--txt);padding:9px 11px;font-size:14px;margin:0 0 12px';
      const labelOf=(p,i)=>(playerName(p)||('Player '+(i+1)))+posSuffixText(p);
      const searchStr=(p,i)=>_fold(labelOf(p,i)+' '+(PIDCUBS_IDX!==undefined?String(p[PIDCUBS_IDX]||''):''));
      const fillOptions=()=>{
        const q=_fold(search.value);
        sel.innerHTML='';
        let matches=players.map((p,i)=>({p:p,i:i})).filter(x=>q===''||searchStr(x.p,x.i).indexOf(q)>=0);
        if(!matches.length){ const o=document.createElement('option');o.value='';o.textContent='No matches';o.disabled=true;sel.appendChild(o); return; }
        matches.forEach(x=>{ const o=document.createElement('option');o.value=String(x.i);o.textContent=labelOf(x.p,x.i);sel.appendChild(o); });
        if(!matches.some(x=>x.i===ddSelIdx)){ ddSelIdx=matches[0].i; }
        sel.value=String(ddSelIdx);
      };
      const holder=document.createElement('div');
