function setMode(m){
  mode=m;
  document.getElementById('measurablesView').style.display = m==='measurables'?'':'none';
  document.getElementById('dataEntryView').style.display = m==='data'?'':'none';
  document.getElementById('modeMeas').classList.toggle('active', m==='measurables');
  document.getElementById('modeData').classList.toggle('active', m==='data');
  const ap=document.getElementById('addPlayer'); if(ap) ap.style.display=m==='measurables'?'':'none';
  if(m==='data') renderDataEntry();
}
