// auto-capitalize the first letter of any text input as the user types
if(typeof document!=='undefined' && document.addEventListener){
  document.addEventListener('input',function(e){
    var t=e.target; if(!t||t.tagName!=='INPUT') return;
    var ty=(t.type||'text'); if(ty!=='text') return;
    var v=t.value; if(v && v.charAt(0)!==v.charAt(0).toUpperCase()){ var pos=t.selectionStart; t.value=v.charAt(0).toUpperCase()+v.slice(1); try{t.setSelectionRange(pos,pos);}catch(_){} }
  },true);
  // when a text field loses focus ("done typing"), title-case every word
  document.addEventListener('focusout',function(e){
    var t=e.target; if(!t||t.tagName!=='INPUT') return;
    var ty=(t.type||'text'); if(ty!=='text') return;
    var v=t.value; if(!v) return;
    var tc=titleCaseStr(v);
    if(tc!==v){ t.value=tc; try{ t.dispatchEvent(new Event('input',{bubbles:true})); t.dispatchEvent(new Event('change',{bubbles:true})); }catch(_){} }
  },true);
  // keyboard: Esc = cancel/close the open dialog, Enter = confirm (primary button)
  document.addEventListener('keydown',function(e){
    var ov=document.getElementById('overlay'), ov2=document.getElementById('overlay2');
    var ov2open=ov2&&ov2.classList.contains('show');
    var ovopen=ov&&ov.classList.contains('show');
    if(!ovopen&&!ov2open) return;
    var top=ov2open?document.getElementById('modal2'):document.getElementById('modal');
    if(!top) return;
    if(e.key==='Escape'){
      e.preventDefault();
      var btns=[].slice.call(top.querySelectorAll('button'));
      var cancelBtn=btns.filter(function(b){return (b.textContent||'').trim().toLowerCase()==='cancel';})[0];
      if(cancelBtn){ cancelBtn.click(); }
      else if(ov2open){ closeModal2(); }
      else { closeModal(); }
      return;
    }
    if(e.key==='Enter'){
      if(ov2open) return; // value pickers have no single "confirm" action
      var tgt=e.target;
      if(tgt && (tgt.tagName==='TEXTAREA'||tgt.tagName==='SELECT')) return;
      var pbtns=[].slice.call(top.querySelectorAll('button.primary'));
      if(pbtns.length){ e.preventDefault(); pbtns[0].click(); }
    }
  });
}
if(events.length){ setActiveEvent(0); }
else { updateGate(); renderPlayers(); renderForm(); }
